mapper.select:
SELECT p.pact_id, p.contract_no, p.contract_name, p.contract_type, p.party_a, p.party_b, p.contract_amount, p.sign_date, p.start_date, p.end_date, p.status, p.execution_status, p.is_manual_modify, p.dept_id, p.emp_id, p.template_config_id, p.main_attach_id, p.remark, p.create_user, p.create_time, p.update_time, COALESCE(e.emp_code, '') AS emp_code, COALESCE(e.emp_name, '') AS emp_name, COALESCE(d.dept_name, '') AS dept_name, COALESCE(e.emp_phone, '') AS emp_phone FROM pact_main p LEFT JOIN sys_emp e ON p.emp_id = e.emp_id LEFT JOIN sys_dept d ON p.dept_id = d.dept_id
AND p.emp_id = #{empId}
AND p.contract_no LIKE CONCAT('%', #{contractNo}, '%')
AND p.contract_name LIKE CONCAT('%', #{contractName}, '%')
AND p.contract_type = #{contractType}
AND p.status = #{status}
AND DATE(p.create_time) >= #{startDate}
AND DATE(p.create_time) <= #{endDate}
ORDER BY p.create_time DESC

mapper.update:
UPDATE pact_main
contract_name = #{contractName}, contract_type = #{contractType}, party_a = #{partyA}, party_b = #{partyB}, contract_amount = #{contractAmount}, sign_date = #{signDate}, start_date = #{startDate}, end_date = #{endDate}, status = #{status}, execution_status = #{executionStatus}, is_manual_modify = #{isManualModify}, dept_id = #{deptId}, emp_id = #{empId}, template_config_id = #{templateConfigId}, main_attach_id = #{mainAttachId}, remark = #{remark},
WHERE pact_id = #{pactId}

mapper.select:
SELECT p.pact_id, p.contract_no, p.contract_name, p.contract_type, p.party_a, p.party_b, p.contract_amount, p.sign_date, p.start_date, p.end_date, p.status, p.execution_status, p.is_manual_modify, p.dept_id, p.emp_id, p.template_config_id, p.main_attach_id, p.remark, p.create_user, p.create_time, p.update_time, COALESCE(e.emp_code, '') AS emp_code, COALESCE(e.emp_name, '') AS emp_name, COALESCE(d.dept_name, '') AS dept_name, COALESCE(e.emp_phone, '') AS emp_phone FROM pact_main p LEFT JOIN sys_emp e ON p.emp_id = e.emp_id LEFT JOIN sys_dept d ON p.dept_id = d.dept_id WHERE p.status = 'APPROVED'
AND p.contract_no LIKE CONCAT('%', #{contractNo}, '%')
AND p.contract_name LIKE CONCAT('%', #{contractName}, '%')
AND p.contract_type = #{contractType}
AND p.execution_status = #{executionStatus}
ORDER BY p.create_time DESC
